/* Revisión editorial original: 150 preguntas breves y 56 de Historia del simulador. */
window.PAES_REVIEW=window.PAES_REVIEW||{short:{},classic:{}};
Object.assign(window.PAES_REVIEW.short, {
  'liberalismo/1/1':{choices:['Redefinieron la legitimidad política y la organización estatal.','Extendieron a toda persona adulta el derecho a elegir gobernantes.','Sustituyeron los Estados territoriales por confederaciones continentales.','Establecieron repúblicas como forma de gobierno en cada caso.']},
  'liberalismo/1/2':{choices:['Soberanía nacional.','Soberanía dinástica.','Legitimismo monárquico.','Absolutismo ilustrado.']},
  'liberalismo/1/3':{choices:['Organizar instituciones y distribuir las atribuciones del poder.','Obtener del monarca español la designación de sus presidentes.','Someter sus constituciones a la aprobación de la metrópoli.','Restablecer el virreinato como autoridad sobre las provincias.']},
  'liberalismo/1/4':{choices:['Estado de derecho.','Soberanía nacional.','Representación política.','Autonomía territorial.']},
  'liberalismo/1/5':{choices:['Difusión estatal de símbolos y relatos de pertenencia común.','Restitución de jurisdicciones señoriales por sobre la ley nacional.','Reconocimiento del linaje real como único vínculo entre habitantes.','Organización del territorio mediante lealtades vasalláticas personales.']},
  'liberalismo/1/6':{text:'¿Qué demanda distingue al republicanismo frente al principio monárquico hereditario del siglo XIX?',choices:['Que los cargos de gobierno no sean patrimonio de una dinastía.','Que la sucesión del jefe de Estado preserve el derecho de linaje.','Que la corona asegure continuidad familiar a la jefatura del Estado.','Que el nacimiento determine quién puede ejercer la máxima autoridad.'],why:'El republicanismo rechaza que la jefatura del Estado se transmita como patrimonio dinástico; el constitucionalismo también puede existir en monarquías.'},
  'liberalismo/1/7':{choices:['Debates sobre constituciones, derechos y representación.','Restablecimiento del privilegio estamental como igualdad jurídica.','Reconocimiento del derecho divino como fundamento de soberanía nacional.','Supeditación de las libertades civiles a la voluntad patrimonial del rey.']},
  'liberalismo/1/8':{choices:['Porque el reconocimiento de derechos convivía con exclusiones electorales.','Porque la igualdad jurídica implicaba idéntica participación electoral.','Porque la ciudadanía electoral dependía solo de residir en el territorio.','Porque las constituciones liberales igualaban los derechos de ambos sexos.']},
  'liberalismo/1/9':{choices:['Construcción de Estados nacionales.','Descentralización de monarquías unificadas.','Restauración de autonomías dinásticas regionales.','Disolución de los vínculos políticos territoriales.']},
  'liberalismo/1/10':{choices:['Cuestionó privilegios jurídicos heredados por nacimiento.','Identificó igualdad jurídica con igual distribución de la riqueza.','Defendió derechos diferenciados según el estamento de origen.','Subordinó los derechos civiles a la pertenencia nobiliaria.']},
  'liberalismo/2/1':{choices:['Libertades civiles reconocidas coexistían con restricciones electorales.','La libertad de imprenta extendía implícitamente el voto a los no propietarios.','El requisito patrimonial convertía ese régimen en monarquía absoluta.','La existencia de elecciones aseguraba iguales derechos políticos a todos.']},
  'liberalismo/2/2':{choices:['La ciudadanía electoral estaba limitada por sexo y patrimonio.','Los no propietarios carecían de cualquier derecho civil reconocido.','Las mujeres propietarias podían votar por cumplir el requisito económico.','El patrimonio determinaba por sí solo todos los derechos individuales.']},
  'liberalismo/2/3':{choices:['Liberalismo político.','Absolutismo ilustrado.','Legitimismo dinástico.','Restauración estamental.']},
  'liberalismo/2/4':{text:'Una cronología registra independencias americanas a comienzos del XIX y unificaciones europeas en la segunda mitad del mismo siglo. ¿Qué permite establecer?',choices:['Hubo construcción estatal en distintos espacios y momentos.','Las independencias americanas causaron directamente cada unificación europea.','Las sociedades europeas y americanas adoptaron iguales formas de gobierno.','Las unificaciones europeas precedieron a las independencias americanas.'],why:'La cronología permite situar procesos comparables sin demostrar por sí sola causalidad, instituciones idénticas ni experiencias uniformes.'},
  'liberalismo/2/5':{choices:['Fortalecer una identidad nacional compartida.','Transferir a los municipios la soberanía exterior.','Restablecer el predominio de identidades dinásticas.','Separar la educación del proyecto de integración estatal.']},
  'liberalismo/2/6':{choices:['Redefinición del vínculo entre personas y poder político.','Equiparación de derechos políticos sin distinción de sexo o renta.','Supresión de las obligaciones del individuo frente a las instituciones.','Conversión de la representación política en una prerrogativa hereditaria.']},
  'liberalismo/2/7':{choices:['Distribución territorial de atribuciones estatales.','Requisitos patrimoniales de la ciudadanía electoral.','Relaciones entre libertad religiosa y confesionalidad.','Controles recíprocos entre legislación y judicatura.']},
  'liberalismo/2/8':{choices:['La igualdad proclamada convivía con exclusiones políticas.','La igualdad ante la ley garantizaba el acceso universal al voto.','La restricción electoral prueba la vigencia de privilegios estamentales.','El discurso del diario describe por sí solo la participación efectiva.']},
  'liberalismo/2/9':{choices:['El constitucionalismo liberal podía coexistir con una monarquía.','La permanencia del rey demostraba ausencia de límites constitucionales.','La existencia de parlamento convertía la jefatura del Estado en republicana.','El título monárquico implicaba que el parlamento carecía de atribuciones.']},
  'liberalismo/2/10':{choices:['Consolidación jurídica y simbólica de nuevos Estados.','Restauración de la legitimidad dinástica de las antiguas coronas.','Sustitución de instituciones nacionales por jurisdicciones señoriales.','Ampliación comprobada del voto a todos los habitantes adultos.']},
  'liberalismo/3/1':{choices:['Registros de escuelas y rituales que difundieron pertenencia nacional.','Memorias militares que narran victorias en conflictos de frontera.','Presupuestos estatales que financian campañas contra países vecinos.','Proclamas que vinculan el sentimiento nacional con triunfos bélicos.']},
  'liberalismo/3/2':{choices:['Contrastar el discurso con el respeto a derechos y pluralismo.','Identificar apoyo mayoritario como autorización para restringir disidencias.','Medir la legitimidad únicamente por la eficacia del gobierno.','Considerar la unidad nacional como prueba de consentimiento opositor.']},
  'liberalismo/3/3':{choices:['Distancia entre igualdad declarada y ciudadanía electoral efectiva.','Equivalencia entre reconocimiento de derechos civiles y sufragio universal.','Incompatibilidad de toda representación con las constituciones liberales.','Sustitución de los requisitos electorales por participación directa universal.']},
  'liberalismo/3/4':{choices:['Surgieron con actores, objetivos y contextos históricos diferentes.','Compartir símbolos nacionales implica buscar idénticas instituciones.','El uso de constituciones garantiza iguales resultados de integración.','La defensa de soberanía nacional supone una misma estructura social.']},
  'liberalismo/3/5':{choices:['Homogeneización nacional y diversidad cultural.','Centralización tributaria y libertad de comercio.','Soberanía dinástica y sucesión hereditaria.','Representación censitaria y autonomía judicial.']},
  'liberalismo/3/6':{choices:['Reconocimiento de límites jurídicos a la autoridad.','Transmisión hereditaria de la jefatura del Estado.','Elección periódica de la máxima autoridad estatal.','Identidad entre soberanía nacional y derecho dinástico.']},
  'liberalismo/3/7':{text:'Un historiador compara tres revoluciones que compartieron ideales liberales, pero tuvieron actores, demandas concretas y desenlaces diferentes. ¿Cuál es la conclusión mejor respaldada?',choices:['Ideales compartidos pueden traducirse en trayectorias distintas.','Las diferencias de desenlace prueban que no hubo ideales comunes.','La similitud de ideales demuestra igualdad de causas sociales.','Las diferencias entre actores impiden comparar procesos revolucionarios.']},
  'liberalismo/3/8':{choices:['Leyes de sufragio y padrones electorales contemporáneos.','Constituciones examinadas sin sus disposiciones electorales.','Discursos que elogian la igualdad sin registros de votantes.','Crónicas de campañas sin requisitos ni nóminas electorales.']},
  'liberalismo/3/9':{choices:['Soberanía popular proclamada y deliberación pública restringida.','Igualdad de voto proclamada y adopción de distritos territoriales.','Representación política proclamada y elecciones periódicas.','Soberanía nacional proclamada y existencia de leyes generales.']},
  'liberalismo/3/10':{choices:['Identificar cambios territoriales documentados por la cartografía.','Deducir de las fronteras la inclusión electoral de cada Estado.','Establecer únicamente desde los límites las causas de las guerras.','Determinar por la superficie territorial la legitimidad del gobierno.']},
  'chile19/1/1':{choices:['El crecimiento exportador no basta para inferir bienestar general.','El índice exportador permite estimar el alza del salario real.','El aumento de ventas externas implica menor desigualdad social.','El crecimiento del índice demuestra mayor consumo en cada hogar.']},
  'chile19/1/2':{choices:['Un Ejecutivo fuerte y amplias atribuciones presidenciales.','Un régimen federal de provincias con soberanía propia.','Una presidencia subordinada jurídicamente a la mayoría parlamentaria.','Un gobierno con autoridades elegidas por sufragio universal adulto.']},
  'chile19/1/3':{choices:['Exportación de recursos mineros y productos agrícolas.','Exportación predominante de maquinaria para países industrializados.','Especialización exportadora en manufacturas textiles de gran escala.','Producción exportadora destinada principalmente al mercado interno.']},
  'chile19/1/4':{choices:['Explotación salitrera del norte.','Extracción de carbón en Arauco.','Producción triguera del valle central.','Explotación de plata en Chañarcillo.'],text:'¿Qué actividad de los territorios incorporados tras la Guerra del Pacífico adquirió especial importancia fiscal y exportadora para Chile?'},
  'chile19/1/5':{choices:['Precariedad de vivienda, salud y trabajo de sectores populares.','Disputas diplomáticas por la delimitación de territorios salitreros.','Conflictos constitucionales sobre atribuciones del Ejecutivo y Congreso.','Debates entre empresarios sobre aranceles a bienes importados.']},
  'chile19/1/6':{choices:['Redes ferroviarias y modernización de puertos.','Fortificaciones fronterizas y cuarteles militares.','Palacios de gobierno y edificios parlamentarios.','Teatros urbanos y monumentos conmemorativos.'],text:'¿Qué infraestructura del Chile del siglo XIX facilitó directamente el traslado masivo de mercancías hacia mercados internos y externos?'},
  'chile19/1/7':{choices:['Expansión urbana y crecimiento del trabajo asalariado.','Predominio creciente de gremios artesanales con privilegios coloniales.','Sustitución del empleo minero por relaciones de encomienda.','Concentración de la población urbana en labores de autosubsistencia.']},
  'chile19/1/8':{choices:['La guerra civil entre fuerzas del Ejecutivo y del Congreso.','La guerra contra la Confederación Perú-Boliviana.','El levantamiento liberal contra el gobierno de Manuel Montt.','La guerra externa por el control de territorios salitreros.']},
  'chile19/1/9':{choices:['Vulnerabilidad ante cambios de precios y demanda mundial.','Protección del ingreso fiscal mediante especialización exportadora.','Estabilidad salarial asegurada por vender a varios compradores.','Autonomía económica derivada de concentrar productos exportados.']},
  'chile19/1/10':{choices:['Mutuales, mancomunales y organizaciones obreras.','Directorios empresariales que fijaban contratos laborales.','Representantes de las compañías salitreras extranjeras.','Asociaciones de hacendados defensoras del inquilinaje.'],text:'¿Qué actores canalizaron demandas de ayuda mutua y defensa colectiva de los trabajadores hacia fines del siglo XIX?'},
  'chile19/2/1':{choices:['Modernización urbana acompañada por desigualdad social.','Expansión del transporte como prueba de mejoras habitacionales generales.','Hacinamiento como evidencia de estancamiento de toda actividad productiva.','Conventillos como consecuencia de la desaparición del empleo asalariado.']},
  'chile19/2/2':{choices:['La expansión exportadora podía coexistir con precariedad urbana.','El hacinamiento demuestra que disminuyó el valor de las exportaciones.','El incremento exportador elevó por igual los ingresos de los hogares.','El cuadro permite atribuir el hacinamiento exclusivamente al comercio.']},
  'chile19/2/3':{choices:['Argumentos sobre instituciones y atribuciones del nuevo Estado.','Niveles de aplicación efectiva de cada norma en todas las provincias.','Opiniones representativas de toda la población sobre la Constitución.','Distribución del ingreso entre hogares a partir del debate jurídico.']},
  'chile19/2/4':{choices:['Inserción exportadora en los mercados industrializados.','Industrialización chilena orientada a vender maquinaria al exterior.','Sustitución de importaciones mediante producción fabril nacional.','Protección del mercado interno mediante reducción del comercio exterior.']},
  'chile19/2/5':{choices:['Ampliación de la conectividad según las nuevas líneas trazadas.','Aumento uniforme de los salarios en las localidades conectadas.','Acceso equivalente de todas las regiones al transporte ferroviario.','Crecimiento demográfico causado exclusivamente por la red ferroviaria.']},
  'chile19/2/6':{choices:['Precariedad habitacional y sanitaria de la cuestión social.','Conflictos diplomáticos por puertos de exportación salitrera.','Debates constitucionales por las atribuciones del Presidente.','Redistribución de la renta fiscal hacia vivienda obrera terminada.']},
  'chile19/2/7':{choices:['Conflictos sobre el equilibrio de atribuciones institucionales.','Una disputa sobre los requisitos patrimoniales del electorado.','La controversia sobre la separación entre Iglesia y Estado.','Un debate acerca del régimen de propiedad de tierras indígenas.']},
  'chile19/2/8':{choices:['Movilidad interna y cambios en la composición del empleo.','Sustitución del trabajo asalariado portuario por inquilinaje rural.','Expansión de la autosubsistencia como principal actividad portuaria.','Desconcentración de población desde centros comerciales hacia haciendas.']},
  'chile19/2/9':{choices:['Construir pertenencia a una comunidad política nacional.','Asegurar por esas medidas la incorporación universal al sufragio.','Reemplazar la soberanía nacional por legitimidad de linaje.','Reconocer a cada localidad como Estado soberano independiente.']},
  'chile19/2/10':{choices:['Exposición del ingreso exportador a fluctuaciones externas.','Descenso comprobado de la cantidad física exportada.','Caída equivalente del salario real en todas las ocupaciones.','Reducción del valor exportado por una causa exclusivamente interna.']},
  'chile19/3/1':{choices:['Exportaciones, salarios reales y condiciones de vivienda.','Precios de exportación y discursos sobre prosperidad nacional.','Ingresos aduaneros y presupuestos de ceremonias públicas.','Tonelajes embarcados y memorias de empresarios exportadores.']},
  'chile19/3/2':{choices:['Distinguir correlación espacial de una causalidad demostrada.','Tomar la cercanía a las vías como prueba de causalidad exclusiva.','Inferir de la densidad que los trenes precedieron a los asentamientos.','Usar la coincidencia regional para descartar otros factores productivos.']},
  'chile19/3/3':{choices:['Dependencia del valor exportado respecto del mercado mundial.','Protección fiscal automática derivada de especializar las exportaciones.','Capacidad de fijar precios externos por controlar yacimientos nacionales.','Compensación salarial inmediata al disminuir los ingresos de exportación.']},
  'chile19/3/4':{choices:['Distribución territorial del poder estatal.','Requisitos de renta para el derecho a voto.','Relación entre la Iglesia y las instituciones civiles.','Distribución de funciones judiciales y legislativas.']},
  'chile19/3/5':{choices:['Informes sanitarios y testimonios de hacinamiento obrero.','Cifras de ingresos fiscales obtenidos por impuestos al salitre.','Registros de inversión en infraestructura portuaria y ferroviaria.','Discursos que celebran la prosperidad de empresarios exportadores.']},
  'chile19/3/6':{choices:['Modernización productiva junto a precariedad de vida urbana.','Aumento del empleo como prueba de bienestar habitacional general.','Mecanización como evidencia de desaparición de la demanda laboral.','Expansión portuaria como indicador de igualdad entre grupos sociales.']},
  'chile19/3/7':{choices:['La ruptura colonial abrió disputas sobre el orden republicano.','La declaración independentista resolvió la distribución territorial del poder.','La derrota realista aseguró de inmediato un consenso constitucional.','La soberanía estatal implicó desde su inicio igual participación política.']},
  'chile19/3/8':{choices:['Programas estatales de educación y ceremonias patrióticas.','Memorias familiares sobre vínculos afectivos con el lugar de origen.','Relatos de viajeros acerca de costumbres compartidas localmente.','Testimonios de adhesión popular sin intervención pública registrada.']},
  'chile19/3/9':{choices:['Relacionar urbanización, trabajo y respuestas de protección.','Explicar la precariedad por características personales de los pobres.','Deducir las condiciones de vida a partir del ingreso aduanero.','Reducir la conflictividad a la retórica de los dirigentes obreros.']},
  'chile19/3/10':{choices:['Inicio independentista → Constitución de 1833 → Guerra del Pacífico → guerra civil de 1891.','Inicio independentista → Guerra del Pacífico → Constitución de 1833 → guerra civil de 1891.','Constitución de 1833 → inicio independentista → Guerra del Pacífico → guerra civil de 1891.','Inicio independentista → Constitución de 1833 → guerra civil de 1891 → Guerra del Pacífico.']},
  'crisisxx/1/1':{choices:['Financiar obras públicas para aumentar la demanda de trabajo.','Reducir el gasto estatal esperando la recuperación espontánea del mercado.','Contraer el crédito para sostener el valor de la moneda.','Recortar salarios públicos para equilibrar el presupuesto fiscal.']},
  'crisisxx/1/2':{choices:['Pretensión de controlar ampliamente sociedad y oposición.','Limitación del gobierno mediante competencia partidaria regulada.','Separación entre propaganda oficial y sistema educativo autónomo.','Reconocimiento de asociaciones opositoras como contrapeso institucional.']},
  'crisisxx/1/3':{choices:['Proteger ante riesgos sociales y ampliar servicios públicos.','Reservar la seguridad social a la beneficencia privada.','Condicionar la asistencia al desempleado a la filiación partidaria.','Sustituir la protección laboral por acuerdos individuales sin regulación.']},
  'crisisxx/1/4':{choices:['La crisis favoreció descontento y respuestas políticas diversas.','El desempleo condujo por sí solo a iguales regímenes políticos.','La integración comercial aseguró iguales respuestas estatales.','La recuperación económica exigió abandonar el pluralismo político.']},
  'crisisxx/1/5':{text:'En algunas experiencias latinoamericanas de la primera mitad del siglo XX, un líder apeló al pueblo y articuló sindicatos en un proyecto nacional. ¿Qué rasgo permite analizarlas como populistas?',choices:['El vínculo político entre liderazgo y movilización popular.','La organización partidaria apoyada solo en notables locales.','La mediación exclusiva de asociaciones de grandes propietarios.','La separación del proyecto nacional respecto de demandas obreras.'],why:'La apelación al pueblo y la articulación de masas con un liderazgo son rasgos de experiencias populistas; el concepto no designa una doctrina única.'},
  'crisisxx/1/6':{text:'¿Qué rasgo caracterizó a la Primera Guerra Mundial entre 1914 y 1918?',choices:['Movilización bélica de potencias agrupadas en alianzas rivales.','Competencia bipolar basada en disuasión nuclear recíproca.','Contención del bloque soviético mediante alianzas occidentales.','Descolonización masiva posterior al debilitamiento europeo de 1945.']},
  'crisisxx/1/7':{choices:['Financiar un programa de obras públicas.','Esperar la contratación mediante rebajas salariales privadas.','Disminuir la inversión fiscal para equilibrar las cuentas.','Confiar la asistencia laboral a organizaciones benéficas.']},
  'crisisxx/1/8':{choices:['Construir adhesión al líder y deslegitimar a la oposición.','Favorecer una deliberación con acceso equivalente para disidentes.','Limitar el culto personal mediante información pública independiente.','Separar la formación cultural de los objetivos del partido gobernante.']},
  'crisisxx/1/9':{choices:['Capacidad institucional para responder a crisis y conflictos sociales.','Conveniencia de restaurar virreinatos en las repúblicas americanas.','Distribución territorial surgida de las unificaciones del siglo XIX.','Definición de requisitos nobiliarios para mantener jerarquías estamentales.']},
  'crisisxx/1/10':{choices:['La protección social no requiere suprimir pluralismo y libertades.','La presencia de seguros sociales identifica un régimen de partido único.','La intervención económica del Estado implica control total de la cultura.','La regulación laboral distingue por sí sola democracia de dictadura.']},
  'crisisxx/2/1':{choices:['Deducir respuestas idénticas de la existencia de una crisis común.','Distinguir la estructura productiva de cada país antes de compararlos.','Relacionar medidas de recuperación con sus resultados sociales.','Examinar las instituciones y coaliciones que decidieron cada política.']},
  'crisisxx/2/2':{choices:['Culto al liderazgo y deslegitimación del disenso.','Competencia partidaria regulada mediante garantías recíprocas.','Apelación electoral compatible con la legitimidad de los adversarios.','Publicidad institucional independiente de la persona gobernante.'],why:'La exaltación personal y la representación de toda crítica como enemiga sugieren tendencias autoritarias; el afiche por sí solo no demuestra la existencia de policía política.'},
  'crisisxx/2/3':{choices:['Ampliación de la protección social mediante políticas públicas.','Ajuste fiscal mediante transferencia de servicios a la beneficencia.','Protección de los ingresos únicamente mediante rebajas tributarias.','Sustitución de la asistencia estatal por ahorro individual voluntario.']},
  'crisisxx/2/4':{text:'Un discurso latinoamericano de mediados del siglo XX presenta a un líder como portavoz directo del pueblo y convoca sindicatos a un proyecto nacional. ¿Qué enfoque ayuda a analizarlo?',choices:['Vínculo entre liderazgo populista y movilización de masas.','Representación restringida mediante partidos de notables.','Continuidad del orden oligárquico ajeno a demandas laborales.','Supresión de la intervención pública en la cuestión social.'],why:'La apelación directa al pueblo y la articulación sindical permiten estudiar rasgos populistas; no bastan para atribuir idénticas políticas a todos esos movimientos.'},
  'crisisxx/2/5':{choices:['Menor crédito puede restringir inversión, producción y empleo.','Menor crédito permite financiar más proyectos sin cambiar otros recursos.','Menor crédito reduce los costos de financiamiento empresarial.','Menor crédito aumenta el consumo por expandir el endeudamiento familiar.']},
  'crisisxx/2/6':{choices:['Concentración política y represión de la disidencia.','Competencia entre partidos dentro de un marco pluralista.','Separación de funciones con control independiente del gobierno.','Organización del debate público mediante libertades recíprocas.']},
  'crisisxx/2/7':{choices:['Situar temporalmente conflictos y crisis de la primera mitad del siglo XX.','Demostrar mediante el orden de fechas una causalidad necesaria.','Deducir de la duración de los hechos su impacto social preciso.','Establecer a partir de las fechas los motivos de cada participante.'],why:'Una cronología sitúa temporalmente los hechos; por sí sola no prueba relaciones causales ni consecuencias sociales.'},
  'crisisxx/2/8':{choices:['Aumentar gasto público para estimular demanda y actividad.','Disminuir salarios para recuperar la actividad solo por ajuste privado.','Restringir el presupuesto público para sostener el equilibrio fiscal.','Contraer el crédito para reducir la cantidad de dinero circulante.']},
  'crisisxx/2/9':{choices:['La menor demanda externa redujo ingresos de exportación.','La depresión elevó la demanda mundial de materias primas.','La especialización primaria protegió los ingresos ante la recesión.','La caída exportadora demuestra un alza general del consumo externo.']},
  'crisisxx/2/10':{choices:['Pretensión totalitaria de modelar ampliamente la vida social.','Constitucionalismo que limita el gobierno a funciones delegadas.','Pluralismo cultural sustentado en asociaciones independientes.','Descentralización educativa ajena a la ideología del gobierno.']},
  'crisisxx/3/1':{choices:['Estudiar crisis, propaganda, organización política y erosión institucional.','Comparar únicamente las tasas de desempleo de distintos países.','Deducir la adhesión política desde el nivel agregado de producción.','Elegir el indicador económico que mejor coincida con la hipótesis.']},
  'crisisxx/3/2':{choices:['Una crisis común puede tener respuestas políticas diferentes.','El desempleo exige restringir el pluralismo antes de recuperarse.','Los seguros sociales son equivalentes a la concentración partidaria.','La política de cada país deriva directamente de la tasa de desempleo.']},
  'crisisxx/3/3':{choices:['Confunde mensajes de adhesión promovidos con aceptación social comprobada.','La difusión oficial permite medir directamente el consentimiento privado.','La repetición del mensaje equivale a testimonios independientes coincidentes.','El carácter público de la propaganda asegura representatividad del apoyo.'],why:'La propaganda permite estudiar lo que el régimen buscaba difundir; para investigar recepción y aceptación deben contrastarse fuentes de diverso origen.'},
  'crisisxx/3/4':{choices:['Los vínculos comerciales y financieros transmitieron la contracción.','La distancia geográfica determinó idéntica caída productiva en cada país.','La especialización exportadora aisló las economías de la recesión mundial.','La menor demanda estadounidense elevó automáticamente ingresos exportadores.']},
  'crisisxx/3/5':{choices:['Existen instrumentos de protección, pero falta evidencia sobre el régimen.','La cobertura social permite establecer que hay competencia partidaria.','El financiamiento público demuestra subordinación política de la judicatura.','La previsión estatal identifica por sí sola un gobierno de partido único.']},
  'crisisxx/3/6':{choices:['Relacionar las fuentes y examinar también organización y demandas laborales.','Usar la coincidencia temporal como prueba de causalidad exclusiva.','Deducir la intensidad de la protesta únicamente del índice de precios.','Atribuir toda movilización a una reacción espontánea sin mediación social.']},
  'crisisxx/3/7':{choices:['Contextualizar actores, liderazgos y estructuras antes de generalizar.','Deducir políticas económicas idénticas desde una retórica popular común.','Aplicar la experiencia de un país como modelo suficiente de los demás.','Clasificar los movimientos únicamente por la popularidad de sus líderes.']},
  'crisisxx/3/8':{choices:['La ampliación de beneficios puede coexistir con prácticas autoritarias.','La cobertura de beneficios demuestra libertad de la prensa opositora.','La censura permite descartar la existencia de redistribución económica.','La protección social equivale a una garantía de alternancia política.']},
  'crisisxx/3/9':{choices:['Empleo, salario real y acceso a servicios antes y después de 1929.','Cotizaciones bursátiles de una jornada sin registros de los hogares.','Presupuestos militares de un año sin indicadores de vida cotidiana.','Discursos presidenciales de recuperación sin series económicas comparables.']},
  'crisisxx/3/10':{choices:['¿Cómo interactuaron crisis, propaganda y represión en su consolidación?','¿Qué indicador económico explica por sí solo todos sus apoyos sociales?','¿Cómo demuestra la popularidad del líder la aceptación de cada medida?','¿Qué rasgo del carácter nacional volvió inevitable cada dictadura?']},
  'guerr_fria/1/1':{choices:['Rivalidad bipolar en las relaciones políticas y estratégicas.','Cooperación estable entre las potencias para integrar sus bloques.','Guerra directa ininterrumpida entre las dos superpotencias.','Sustitución de los Estados europeos por una autoridad supranacional.']},
  'guerr_fria/1/2':{choices:['Declaración Universal de Derechos Humanos.','Carta de las Naciones Unidas.','Convención Europea de Derechos Humanos.','Convención Americana sobre Derechos Humanos.']},
  'guerr_fria/1/3':{choices:['Rivalidad sistémica sin guerra general directa entre superpotencias.','Equilibrio entre potencias sin competencia ideológica o tecnológica.','Alianza estable de las superpotencias para dirigir un mismo bloque.','Confrontación militar directa continua entre sus ejércitos nacionales.'],why:'Las superpotencias compitieron política, militar y culturalmente sin una guerra general directa entre ambas. Eso no equivale a ausencia de guerras regionales ni de enfrentamientos limitados.'},
  'guerr_fria/1/4':{choices:['Predominio de dos superpotencias y sus áreas de influencia.','Reparto de poder equivalente entre todas las potencias europeas.','Supremacía compartida entre países no alineados de Asia y África.','Sustitución de los bloques por un único gobierno internacional.']},
  'guerr_fria/1/5':{choices:['Independencia política de numerosos territorios coloniales.','Autonomía económica completa como requisito previo de soberanía.','Sustitución de metrópolis europeas por administraciones coloniales comunes.','Integración obligatoria de excolonias en sus antiguas metrópolis.']},
  'guerr_fria/1/6':{choices:['Competencia tecnológica y simbólica entre superpotencias.','Cooperación científica que sustituyó la rivalidad entre bloques.','Separación de la investigación espacial respecto de objetivos estratégicos.','Transferencia del liderazgo tecnológico a los países no alineados.']},
  'guerr_fria/1/7':{text:'¿Qué episodio de 1962 enfrentó a Estados Unidos y la URSS por la instalación de armamento nuclear en el Caribe?',choices:['Crisis de los misiles en Cuba.','Bloqueo soviético de Berlín.','Intervención de la ONU en Corea.','Crisis anglo-francesa del canal de Suez.']},
  'guerr_fria/1/8':{choices:['Intensificación de intercambios económicos y comunicacionales globales.','Sustitución del comercio multilateral por circuitos cerrados de cada bloque.','Generalización de la autarquía como modelo de integración internacional.','Reducción de la inversión transnacional por desaparición de redes financieras.']},
  'guerr_fria/1/9':{choices:['La caída del Muro de Berlín en 1989.','La firma del Acta Final de Helsinki en 1975.','La creación del Pacto de Varsovia en 1955.','La construcción del Muro de Berlín en 1961.']},
  'guerr_fria/1/10':{choices:['Reformas, revoluciones y dictaduras en contextos nacionales diversos.','Trayectorias institucionales homogéneas decididas por una misma potencia.','Expansión regional de democracias sin rupturas institucionales.','Resolución de los conflictos sociales mediante neutralidad continental.']},
  'guerr_fria/2/1':{choices:['Relacionar influencia externa con actores y tensiones internas.','Explicar las decisiones locales como ejecución automática de órdenes externas.','Usar el apoyo financiero para atribuir iguales fines a todos los aliados.','Deducir del enfrentamiento global que las demandas nacionales eran idénticas.']},
  'guerr_fria/2/2':{choices:['ONU → Declaración de DD. HH. → crisis de Cuba → caída del Muro.','Declaración de DD. HH. → ONU → crisis de Cuba → caída del Muro.','ONU → Declaración de DD. HH. → caída del Muro → crisis de Cuba.','ONU → crisis de Cuba → Declaración de DD. HH. → caída del Muro.']},
  'guerr_fria/2/3':{choices:['Organización de bloques de influencia política y militar.','Integración de todos los países europeos en un mismo pacto.','Distribución colonial entre potencias europeas de territorios africanos.','No alineamiento de los Estados europeos respecto de las superpotencias.']},
  'guerr_fria/2/4':{choices:['Descolonización e independencia política.','Integración colonial con autogobierno subordinado.','Formación de un protectorado administrado por la metrópoli.','Restablecimiento del dominio imperial europeo.']},
  'guerr_fria/2/5':{choices:['Articulación entre rivalidad bipolar y alianzas regionales.','Neutralidad estratégica del aliado respecto de los bloques.','Transferencia de la soberanía jurídica del aliado a la superpotencia.','Desaparición de las causas internas de los conflictos nacionales.']},
  'guerr_fria/2/6':{choices:['Universalidad de los derechos humanos.','Reciprocidad de derechos entre Estados aliados.','Ciudadanía como requisito de dignidad humana.','Nacionalidad como fundamento exclusivo de derechos.']},
  'guerr_fria/2/7':{choices:['Mayor integración mediante flujos transnacionales.','Autosuficiencia económica de los mercados nacionales.','Equivalencia de beneficios entre todos los grupos sociales.','Disminución de la importancia de las redes de comunicación.']},
  'guerr_fria/2/8':{choices:['Enfrentamiento indirecto mediante actores de una guerra regional.','Guerra directa entre los ejércitos de ambas superpotencias.','Cooperación multilateral con un mando militar compartido.','Neutralidad recíproca frente a los conflictos de terceros países.']},
  'guerr_fria/2/9':{choices:['Confrontación ideológica de proyectos políticos y económicos.','Distribución territorial de recursos naturales sin debate político.','Disuasión nuclear medida mediante inventarios de armamento.','Acuerdos comerciales demostrados por volúmenes de intercambio.']},
  'guerr_fria/2/10':{choices:['Cooperación institucional y persistencia de intereses divergentes.','Capacidad de la ONU para imponer consenso a cada Estado miembro.','Pérdida automática de soberanía al ingresar a un organismo multilateral.','Convergencia obligatoria de políticas exteriores después de cada debate.']},
  'guerr_fria/3/1':{choices:['Continuaron guerras regionales y surgieron nuevas disputas.','Se disolvió la Unión Soviética y desapareció el Pacto de Varsovia.','Se abrieron relaciones diplomáticas antes obstaculizadas.','Se redujeron algunos arsenales mediante acuerdos de cooperación.']},
  'guerr_fria/3/2':{choices:['Disputas por prestigio en cine, propaganda y competencias deportivas.','Inventarios de misiles y presupuestos destinados a armamentos.','Tratados de defensa y acuerdos para instalar bases militares.','Mapas de alianzas y ubicación de tropas en fronteras europeas.']},
  'guerr_fria/3/3':{choices:['La soberanía política no asegura autonomía económica plena.','La dependencia comercial equivale a seguir siendo jurídicamente una colonia.','El intercambio con una antigua metrópoli anula la soberanía estatal.','La independencia requiere terminar toda vinculación con mercados externos.']},
  'guerr_fria/3/4':{text:'Un estudio explica las revoluciones, reformas y dictaduras latinoamericanas como resultados idénticos de la rivalidad entre superpotencias. ¿Qué objeción metodológica es más sólida?',choices:['No considera diferencias en actores, conflictos y contextos nacionales.','Separa las políticas nacionales del enfrentamiento internacional.','Da un peso excesivo a las diferencias entre organizaciones locales.','Atribuye la rivalidad bipolar a los conflictos internos latinoamericanos.'],why:'La explicación reduce procesos heterogéneos a un único resultado externo. Evaluar la influencia internacional exige considerar también actores, conflictos y decisiones nacionales.'},
  'guerr_fria/3/5':{choices:['Un referente internacional para evaluar vulneraciones de derechos.','Una sentencia judicial que determina responsabilidades en cada caso.','Una derogación automática de toda norma nacional incompatible.','Un acuerdo limitado a proteger derechos de Estados miembros aliados.']},
  'guerr_fria/3/6':{choices:['También actuaron reformas, crisis económicas y movilizaciones políticas.','La caída del Muro fue la única causa de las reformas soviéticas previas.','La crisis soviética comenzó exclusivamente después de la reunificación.','El cambio de fronteras explica por sí solo las decisiones de todos los actores.']},
  'guerr_fria/3/7':{choices:['Hubo no alineamiento y márgenes diversos de autonomía nacional.','La existencia de dos bloques implicaba ausencia de Estados soberanos.','Los países no alineados constituyeron un bloque militar tan integrado como la OTAN.','La pertenencia a una alianza aseguraba obediencia idéntica de todos sus miembros.']},
  'guerr_fria/3/8':{text:'Un indicador muestra que aumentó el volumen real del comercio mundial después de 1991. ¿Qué inferencia es indebida a partir de ese único indicador?',choices:['Que el crecimiento comercial benefició por igual a todos los grupos.','Que aumentó el volumen agregado de intercambios internacionales.','Que hubo mayores flujos comerciales entre economías nacionales.','Que el comercio medido era superior al del período comparado.']},
  'guerr_fria/3/9':{choices:['Intereses estratégicos frente a compromisos de derechos humanos.','Cooperación económica frente a la firma de alianzas militares.','Asistencia exterior frente al mantenimiento de relaciones diplomáticas.','Defensa territorial frente a la participación en organismos internacionales.']},
  'guerr_fria/3/10':{choices:['Contrasta objetivos oficiales con experiencias de actores locales.','Convierte la coincidencia de relatos en garantía de neutralidad.','Asegura representatividad social por acumular discursos gubernamentales.','Resuelve discrepancias dando prioridad automática a la versión estatal.']},
  'chilexx/1/1':{choices:['Interrupción del orden democrático por el golpe de 1973.','Expansión de las demandas sociales mediante movilización pública.','Competencia electoral entre proyectos de reforma en los años sesenta.','Transferencia presidencial conforme a elecciones realizadas en democracia.'],viz:{kind:'timeline',entries:[['Décadas de 1950–1960','Movilización y reformas'],['1973','Golpe de Estado'],['1988','Plebiscito'],['1990','Asunción de un gobierno democrático']]},why:'El golpe de Estado de 1973 quebró el orden democrático. El plebiscito de 1988 y el cambio de gobierno de 1990 son hitos diferentes de la recuperación democrática.'},
  'chilexx/1/2':{choices:['1973.','1970.','1980.','1988.']},
  'chilexx/1/3':{choices:['Supresión de garantías y violaciones sistemáticas de derechos humanos.','Competencia partidaria regulada por garantías equivalentes para opositores.','Subordinación de las Fuerzas Armadas a autoridades civiles electas.','Ejercicio de libertades públicas con control judicial efectivo de la represión.']},
  'chilexx/1/4':{choices:['El triunfo del No en el plebiscito sobre continuidad presidencial.','La elección presidencial que llevó a Patricio Aylwin al gobierno.','El traspaso del mando presidencial a un gobierno democrático.','La aprobación plebiscitaria inicial de la Constitución de 1980.']},
  'chilexx/1/5':{choices:['1990.','1988.','1989.','1991.']},
  'chilexx/1/6':{choices:['Migración desde áreas rurales hacia centros urbanos.','Retorno masivo desde los centros industriales hacia las haciendas.','Expansión de la población rural por encima de la urbana.','Despoblamiento de las periferias por concentración en zonas agrícolas.']},
  'chilexx/1/7':{choices:['Incorporación progresiva de nuevos grupos a la participación pública.','Aumento del ingreso exportador como equivalente de igualdad política.','Extensión de beneficios como sustituto de la organización ciudadana.','Reconocimiento de ciudadanía sujeto a la pertenencia a élites tradicionales.']},
  'chilexx/1/8':{choices:['Expansión de mecanismos de mercado y privatizaciones.','Profundización de la sustitución de importaciones con alta protección.','Consolidación del área social mediante nuevas nacionalizaciones industriales.','Extensión de la redistribución de tierras mediante expropiaciones agrarias.']},
  'chilexx/1/9':{choices:['Denunciar abusos y brindar apoyo a las personas afectadas.','Dictar sentencias penales en reemplazo de los tribunales.','Ejercer jurisdicción obligatoria sobre los organismos de seguridad.','Expedir indultos y amnistías mediante decisiones de sus directorios.']},
  'chilexx/1/10':{choices:['Movilización social, articulación opositora y acuerdos políticos.','Sustitución de la organización civil por reformas decididas solo desde el régimen.','Conversión automática del crecimiento económico en competencia electoral.','Traspaso inmediato del gobierno como consecuencia de las protestas de 1983.']},
  'chilexx/2/1':{choices:['Contrastar registros y testimonios atendiendo a contexto y corroboración.','Dar prioridad invariable al documento administrativo frente al testimonio.','Tratar cada coincidencia como prueba de independencia entre las fuentes.','Resolver discrepancias eligiendo la versión que confirma la hipótesis inicial.']},
  'chilexx/2/2':{text:'Un testimonio recreado describe censura de prensa y prohibición de reuniones opositoras en Chile en 1975. ¿Qué característica del régimen permite identificar?',choices:['Restricción autoritaria de libertades públicas.','Competencia política con garantías para la oposición.','Alternancia electoral entre coaliciones de gobierno.','Autonomía de las asociaciones frente al control político.'],why:'La censura y la prohibición de reuniones muestran restricción de libertades; el contexto chileno de 1975 corresponde a la dictadura.'},
  'chilexx/2/3':{choices:['Integridad personal y protección frente a detenciones arbitrarias.','Libertad de enseñanza y elección de establecimientos educacionales.','Derecho a sindicalización y negociación de condiciones de trabajo.','Libertad de desplazamiento internacional y derecho de asilo.']},
  'chilexx/2/4':{choices:['Golpe de Estado → plebiscito → asunción de gobierno democrático.','Golpe de Estado → asunción de gobierno democrático → plebiscito.','Plebiscito → golpe de Estado → asunción de gobierno democrático.','Asunción de gobierno democrático → plebiscito → golpe de Estado.']},
  'chilexx/2/5':{choices:['Rechazar la continuidad de Pinochet prevista en el plebiscito.','Elegir directamente al nuevo presidente entre candidatos opositores.','Aprobar una Constitución distinta mediante asamblea constituyente.','Pronunciarse sobre las reformas constitucionales negociadas en 1989.']},
  'chilexx/2/6':{choices:['Demandas urbanas vinculadas a la migración interna.','Redistribución de tierras mediante la reforma agraria.','Movilidad internacional por expulsión y exilio político.','Descentralización productiva desde ciudades hacia haciendas.']},
  'chilexx/2/7':{choices:['Formas de organización civil frente a la dictadura.','Alcance de la asistencia social como prueba de apoyo al régimen.','Participación exclusivamente electoral de las redes comunitarias.','Homogeneidad ideológica de quienes integraban cada protesta.']},
  'chilexx/2/8':{choices:['Reformas económicas de orientación neoliberal.','Industrialización sustitutiva con protección arancelaria elevada.','Expansión del área social mediante nacionalizaciones productivas.','Planificación central con asignación estatal de toda la producción.']},
  'chilexx/2/9':{choices:['Ampliación de la ciudadanía política a nuevos grupos.','Aumento del electorado explicado solo por crecimiento demográfico.','Equiparación inmediata de participación electoral y bienestar material.','Extensión del voto como garantía de ausencia de futuras exclusiones.']},
  'chilexx/2/10':{choices:['Documentar experiencias de víctimas y patrones de represión.','Emitir sentencias penales definitivas contra cada responsable.','Sustituir la investigación judicial mediante acuerdos administrativos.','Garantizar que cada testimonio represente a todas las víctimas.']},
  'chilexx/3/1':{choices:['Relacionar el plebiscito con movilización, acuerdos e instituciones.','Reconstruir solo los cómputos electorales para explicar toda la transición.','Deducir del triunfo del No que previamente existían garantías equivalentes.','Atribuir la decisión de cada votante exclusivamente a la campaña televisiva.']},
  'chilexx/3/2':{choices:['Distinguir explicaciones debatidas de vulneraciones documentadas.','Considerar cada versión política igualmente corroborada por ser diferente.','Valorar los testimonios según su coincidencia con la interpretación elegida.','Deducir legitimidad del golpe de las causas invocadas por sus partidarios.']},
  'chilexx/3/3':{text:'Si una gráfica del PIB solo registrara crecimiento en algunos años de la dictadura, ¿qué conclusión NO permitiría extraer por sí sola?',choices:['Que el bienestar y los derechos mejoraron por igual para todos.','Que aumentó la producción agregada medida en los años señalados.','Que la serie registró variaciones de actividad durante el período.','Que el indicador permite comparar el nivel de producción entre esos años.'],source:'Situación de análisis hipotética: se dispone únicamente de una serie comparable de PIB real con crecimiento en ciertos años; no se aportan indicadores de distribución ni derechos.'},
  'chilexx/3/4':{choices:['Fueron componentes distintos de un proceso de recuperación democrática.','Las protestas reemplazaron la necesidad de articulación política opositora.','La convocatoria plebiscitaria anuló la incidencia de organizaciones civiles.','El resultado electoral demuestra que la movilización tuvo una causa única.']},
  'chilexx/3/5':{choices:['Prensa diversa, programas, resultados electorales y testimonios.','Discursos de un partido y memorias de sus dirigentes nacionales.','Propaganda de campaña y cómputos sin contexto institucional.','Versiones oficiales del régimen y comunicados que las reproducen.']},
  'chilexx/3/6':{choices:['El plebiscito fue en 1988; el traspaso presidencial ocurrió en 1990.','El triunfo del No produjo ese día la asunción del presidente democrático.','El cambio presidencial precedió a las elecciones generales de 1989.','La aprobación constitucional de 1980 dio inicio al gobierno democrático.']},
  'chilexx/3/7':{choices:['Garantías de competencia y libertad para la oposición.','Existencia de padrones y procedimientos de recuento.','Uso de campañas para movilizar a los electores.','Participación de autoridades en la organización del acto.']},
  'chilexx/3/8':{choices:['Que aumentó necesariamente el bienestar de todos los hogares urbanos.','Que hubo desplazamientos de población desde áreas rurales a urbanas.','Que el mayor peso urbano podía generar nuevas demandas de servicios.','Que cambió la distribución territorial de parte de la población.'],why:'La urbanización y la migración no bastan para inferir una mejora general del bienestar: se requieren indicadores de vivienda, ingresos y servicios.'},
  'chilexx/3/9':{choices:['Permite examinar vías civiles y partidarias diferentes de resistencia.','Permite atribuir a todas las organizaciones un mismo programa electoral.','Demuestra que la denuncia de abusos dependía solo de estructuras partidarias.','Permite sustituir la historia de víctimas por el análisis de campañas.']},
  'chilexx/3/10':{choices:['Una visión de dimensiones políticas y sociales de la democratización.','Una medición del bienestar obtenida exclusivamente de requisitos electorales.','Una explicación del cambio social determinada solo por acceso a vivienda.','Una descripción de participación femenina equivalente a sufragio efectivo.']}
});
Object.assign(window.PAES_REVIEW.classic, {
  '1':{choices:['Igualdad ante la ley y límites constitucionales al poder.','Igualdad jurídica entendida como igualación obligatoria de fortunas.','Representación política fundada en privilegios jurídicos de nacimiento.','Soberanía del monarca como fuente superior a las normas escritas.']},
  '2':{choices:['Soberanía de la comunidad y responsabilidad de sus gobernantes.','Legitimidad de linaje como fundamento de la representación.','Soberanía personal de quienes ejercen la autoridad pública.','Autonomía del gobernante respecto de quienes lo representan.']},
  '3':{choices:['Unificaciones de Italia y Alemania.','Expansión de protectorados europeos en África.','Restauración de privilegios de jurisdicciones señoriales.','Consolidación de fidelidades políticas dinásticas locales.']},
  '4':{choices:['Construcción de pertenencia nacional con exclusiones de ciudadanía.','Igualdad electoral efectiva derivada de declarar soberanía nacional.','Reemplazo inmediato de las jerarquías económicas por igualdad material.','Unificación de las repúblicas mediante una misma autoridad continental.']},
  '5':{choices:['Definir autoridades y reglas de funcionamiento del nuevo Estado.','Obtener del rey español la designación de autoridades provinciales.','Restablecer instituciones virreinales subordinadas a la metrópoli.','Organizar un gobierno dinástico con sucesión de la presidencia por linaje.']},
  '6':{choices:['Inserción exportadora basada en productos primarios.','Predominio de maquinaria chilena en los mercados industriales.','Orientación de la producción exportable solo al consumo nacional.','Aislamiento comercial como condición del desarrollo minero.']},
  '7':{choices:['Precariedad habitacional y sanitaria en sectores populares.','Mejora uniforme de vivienda derivada del crecimiento exportador.','Sustitución del trabajo urbano asalariado por inquilinaje agrícola.','Reducción de la migración interna por expansión del empleo portuario.']},
  '8':{text:'¿Qué transformación se vinculó directamente con la articulación de demandas de los trabajadores en Chile hacia fines del siglo XIX y comienzos del XX?',choices:['Creciente organización del movimiento obrero.','Ampliación de los derechos aduaneros cobrados al salitre.','Fortalecimiento del predominio político de los notables.','Restricción de la ayuda social a iniciativas empresariales.']},
  '9':{choices:['Protección ante accidentes y mejores condiciones de trabajo.','Rebaja de aranceles para abaratar exportaciones de materias primas.','Incentivos fiscales a la inversión de empresarios en nuevos yacimientos.','Libertad empresarial para fijar unilateralmente las jornadas laborales.']},
  '10':{choices:['Desempleo y desprotección agudizados por la Gran Depresión.','La recuperación económica uniforme de los países industrializados.','La solución de crisis bancarias mediante ajustes privados sin costos sociales.','La desvinculación entre quiebras financieras y empleo de trabajadores.']},
  '11':{choices:['Concentración del poder y represión organizada de opositores.','Pluralidad partidaria subordinada a controles judiciales independientes.','Alternancia política garantizada entre proyectos ideológicos rivales.','Separación de la educación pública respecto de la ideología oficial.']},
  '12':{choices:['Ampliar la protección ante riesgos económicos y sociales.','Reservar la asistencia al desempleo a la beneficencia particular.','Subordinar los seguros sociales a lealtades personales con el gobernante.','Sustituir la regulación del trabajo por contratos sin protección pública.']},
  '13':{choices:['Articulación de liderazgo político con movilización popular.','Representación exclusivamente mediante notables de élites terratenientes.','Separación entre sindicatos y todo proyecto político nacional.','Retiro de las demandas laborales de la organización gubernamental.']},
  '14':{choices:['Organización de las Naciones Unidas.','Sociedad de Naciones.','Organización del Tratado del Atlántico Norte.','Organización de los Estados Americanos.']},
  '15':{choices:['Formación de nuevos Estados políticamente independientes.','Autonomía económica completa de cada antigua colonia.','Transferencia de la soberanía colonial a un gobierno mundial.','Desaparición de las fronteras entre territorios recién independizados.']},
  '16':{choices:['Bipolaridad de la Guerra Fría.','Equilibrio multipolar europeo anterior a 1914.','Unipolaridad posterior a la disolución soviética.','Concierto monárquico europeo de la Restauración.']},
  '17':{choices:['La disputa global se articuló con conflictos y proyectos locales.','Las superpotencias decidieron todas las acciones sin iniciativa regional.','La adhesión a un bloque anuló las diferencias entre países aliados.','La rivalidad externa sustituyó las demandas sociales de cada país.']},
  '18':{choices:['Caída del Muro de Berlín en 1989.','Inicio de la perestroika en 1985.','Firma del Acta Final de Helsinki en 1975.','Constitución del Pacto de Varsovia en 1955.']},
  '19':{choices:['Globalización de intercambios, inversiones y cadenas productivas.','Autosuficiencia mediante separación de los circuitos financieros.','Regionalización sin intercambio entre bloques comerciales.','Sustitución de inversiones transnacionales por mercados locales cerrados.']},
  '20':{choices:['Aumento de la proporción urbana en la población total.','Disminución demostrada del número absoluto de habitantes rurales.','Desplazamiento del total de la población rural hacia las ciudades.','Crecimiento de la población urbana exclusivamente por migración rural.'],why:'Los porcentajes permiten comparar proporciones urbanas y rurales. Sin totales ni datos migratorios no prueban cambios absolutos ni explican por sí solos sus causas.'},
  '21':{choices:['Expansión periférica con insuficiencia de vivienda y servicios.','Reducción de demanda habitacional por concentración del empleo.','Equiparación del acceso a servicios entre centros y periferias.','Retorno general al trabajo agrícola por exceso de vivienda urbana.']},
  '22':{choices:['Ampliación de derechos y participación con avances y rupturas.','Incorporación electoral sin exclusiones desde inicios de siglo.','Crecimiento continuo del pluralismo incluso durante la dictadura.','Extensión de derechos que volvió innecesarias las organizaciones sociales.']},
  '23':{choices:['Contrastar explicaciones con fuentes y contexto del quiebre democrático.','Equiparar la validez de interpretaciones sin evaluar sus evidencias.','Elegir la versión más difundida como garantía de rigor histórico.','Confundir explicar las causas con justificar las violaciones de derechos.']},
  '24':{choices:['Restricción de libertades y debilitamiento de garantías jurídicas.','Competencia política con protección equivalente de los adversarios.','Control efectivo de la represión mediante rendición pública de cuentas.','Ejercicio de la oposición con garantías de reunión y expresión.']},
  '25':{choices:['Privatizaciones, apertura comercial y mayor función del mercado.','Profundización de la protección industrial mediante altos aranceles.','Ampliación del área social con expropiaciones generales de industrias.','Continuidad de la redistribución agraria mediante nuevas expropiaciones.']},
  '26':{choices:['Plebiscito sobre la continuidad presidencial de Pinochet.','Elecciones presidenciales y parlamentarias que ganó la oposición.','Traspaso del mando presidencial al primer gobierno de la transición.','Plebiscito de reformas constitucionales acordadas con la oposición.']},
  '27':{choices:['Comparar procedencia, contenido y uso de sus documentos.','Preferir la interpretación más reciente sin revisar sus fuentes.','Dar igual valor probatorio a cada documento por ser una fuente histórica.','Elegir la explicación con mayor número de citas sin analizar pertinencia.']},
  '28':{choices:['Creación de la ONU → golpe de 1973 → plebiscito de 1988.','Golpe de 1973 → creación de la ONU → plebiscito de 1988.','Creación de la ONU → plebiscito de 1988 → golpe de 1973.','Plebiscito de 1988 → golpe de 1973 → creación de la ONU.']},
  '29':{choices:['Reconoció un referente internacional de derechos inherentes a las personas.','Creó un tribunal con jurisdicción penal automática sobre todos los países.','Derogó por su aprobación las leyes nacionales contrarias a sus principios.','Condicionó la titularidad de derechos a la pertenencia a Estados aliados.']},
  '30':{t:'chilexx',choices:['Una experiencia familiar no basta para representar a toda la sociedad.','Su carácter personal impide usarlo para estudiar procesos migratorios.','Su coincidencia con una tendencia general prueba cada detalle del relato.','La distancia temporal garantiza mayor precisión que un registro contemporáneo.']},
  '31':{choices:['Incorporación de nuevos actores al debate y la organización pública.','Igualación automática de la influencia política de todos los ciudadanos.','Sustitución de la representación partidaria por participación escolar directa.','Desaparición de diferencias sociales como resultado de la alfabetización.']},
  '32':{text:'¿Qué acontecimiento se ubica después de la Primera Guerra Mundial y antes del inicio de la Segunda Guerra Mundial?',choices:['Inicio de la Gran Depresión en 1929.','Revolución rusa en 1917.','Creación de la ONU en 1945.','Crisis del canal de Suez en 1956.'],why:'La Primera Guerra Mundial terminó en 1918; la Segunda comenzó en 1939. El inicio de la Gran Depresión en 1929 corresponde al período de entreguerras.'},
  '33':{choices:['Una caída de precios externos puede reducir ingresos fiscales y laborales.','El menor ingreso exportador asegura una mejora del salario real.','La concentración exportadora estabiliza los ingresos frente a crisis externas.','La caída del precio demuestra por sí sola una menor producción física.']},
  '34':{choices:['Relacionar condiciones políticas, económicas, culturales y sociales.','Deducir las motivaciones de cada actor únicamente de su ingreso.','Explicar el proceso desde la voluntad de su principal dirigente.','Atribuir al resultado final una causa inevitable presente desde el inicio.']},
  '35':{choices:['Nuevas instituciones soberanas junto a persistentes desigualdades.','Independencia política acompañada de igualdad económica inmediata.','Cambios de autoridades sin ruptura de la soberanía de la metrópoli.','Extensión automática del voto universal al promulgar constituciones.']},
  '66':{text:'¿Qué alternativa ordena los siguientes hechos desde el más antiguo al más reciente?\nI. Inicio de la Gran Depresión de 1929\nII. Inicio de la Primera Guerra Mundial\nIII. Revolución rusa\nIV. Firma del Tratado de Versalles',choices:['II, III, IV, I','II, IV, III, I','III, II, IV, I','II, III, I, IV']},
  '67':{choices:['Alta dependencia fiscal de los derechos de exportación del salitre.','Financiamiento estatal predominante mediante impuestos personales a la renta.','Diversificación fiscal suficiente para neutralizar las oscilaciones del salitre.','Participación salitrera subordinada a los impuestos de manufacturas exportadas.']},
  '68':{choices:['Organización de mutuales, mancomunales y sociedades de resistencia.','Reemplazo de la ayuda mutua por seguros públicos de cobertura universal.','Sustitución de la organización obrera por negociaciones solo individuales.','Acceso generalizado a vivienda salubre financiada por compañías salitreras.']},
  '69':{choices:['Competencia imperial por territorios, recursos y áreas de influencia.','Aplicación de la autodeterminación mediante consultas a pueblos africanos.','Organización de una federación africana con representación política igualitaria.','Devolución de jurisdicciones coloniales a autoridades soberanas preexistentes.'],why:'La conferencia reguló aspectos de la expansión colonial europea en África, sin representar a sus pueblos. Se inscribe en la competencia imperial; no debe entenderse como un reparto completo de todas las fronteras en una sola reunión.'},
  '70':{choices:['Urbanización y expansión del trabajo obrero asalariado.','Predominio de talleres gremiales sobre producción fabril mecanizada.','Sustitución de salarios fabriles por prestaciones serviles hereditarias.','Desconcentración de trabajadores desde fábricas hacia autosubsistencia.']},
  '71':{text:'Respecto de las consecuencias de la Guerra del Pacífico (1879–1884) para Chile, evalúa las siguientes afirmaciones:\nI. Chile incorporó Tarapacá y afianzó el control de Antofagasta, cuya cesión definitiva por Bolivia se formalizó en 1904.\nII. Aumentaron los ingresos fiscales vinculados a la exportación de salitre.\nIII. La incorporación territorial convirtió toda la producción salitrera en propiedad estatal.',choices:['Solo I y II.','Solo I y III.','Solo II y III.','I, II y III.'],why:'La expansión territorial y los acuerdos posteriores consolidaron el control chileno de áreas salitreras. El Estado obtuvo rentas mediante impuestos, mientras la explotación mantuvo una importante participación privada.'},
  '72':{text:'¿Qué caracterizó la ocupación de la Araucanía por el Estado chileno entre 1861 y 1883 y sus efectos posteriores?',choices:['Avance militar y pérdida de autonomía mapuche, seguidos de radicación territorial.','Reconocimiento de soberanía mapuche permanente dentro de una confederación estatal.','Integración negociada que conservó íntegramente las tierras de las comunidades.','Transferencia de autoridad fiscal y militar del Estado a comunidades autónomas.'],why:'El avance militar consolidó el control estatal del territorio y produjo desposesión y pérdida de autonomía mapuche. La radicación mediante títulos de merced se desarrolló principalmente entre 1884 y 1929.'},
  '73':{choices:['Partido único, culto al líder y represión de la disidencia.','Competencia partidaria bajo control de tribunales independientes.','Autonomía cultural de asociaciones opositoras frente al gobierno.','Separación entre propaganda partidaria y educación pública plural.'],why:'Pese a diferencias ideológicas y nacionales, estos regímenes concentraron poder, promovieron el culto al líder y persiguieron a sus opositores. Compartir rasgos no vuelve idénticas sus trayectorias.'},
  '74':{choices:['Fomentar la producción industrial con una función estatal más activa.','Sostener la recuperación mediante mayor especialización salitrera.','Reducir el fomento público para depender solo del crédito extranjero.','Cubrir el consumo interno ampliando la importación de manufacturas.']},
  '75':{choices:['Acercó a las superpotencias a una confrontación nuclear directa.','Concluyó la rivalidad nuclear al garantizar un desarme general.','Convirtió el conflicto bipolar en una alianza militar permanente.','Resolvió la división europea mediante la reunificación alemana.']},
  '76':{choices:['Debilitamiento de metrópolis y movilización nacionalista anticolonial.','Fortalecimiento imperial europeo que volvió innecesarias las negociaciones.','Reemplazo de movimientos independentistas por administración colonial conjunta.','Desaparición de demandas de autodeterminación tras la guerra mundial.']},
  '77':{text:'Considerando la fuente y el contexto posterior a la Revolución cubana de 1959, ¿cómo puede interpretarse la Alianza para el Progreso impulsada por Estados Unidos en 1961?',choices:['Ayuda y reformas vinculadas a contener la influencia revolucionaria regional.','Cooperación social desvinculada de objetivos estratégicos de la Guerra Fría.','Asistencia orientada a frenar reformas agrarias y preservar intacto el latifundio.','Programa de integración de gobiernos latinoamericanos al bloque soviético.'],source:'Paráfrasis didáctica: el programa ofrecía financiamiento para vivienda, educación y reforma agraria. Contexto histórico: Estados Unidos lo promovió después de la Revolución cubana para impulsar desarrollo y reducir la expansión de movimientos revolucionarios en la región.',why:'La fuente muestra instrumentos sociales y el contexto añadido permite relacionarlos con una estrategia estadounidense de contención. La dimensión geopolítica no se deduce únicamente de que existiera ayuda económica.'},
  '78':{choices:['Redistribuir tierras y modernizar la producción agrícola.','Concentrar tierras mediante ampliación del latifundio tradicional.','Conservar el inquilinaje como base de la organización productiva.','Sustituir la actividad campesina por un mercado solo de importaciones.']},
  '79':{text:'Sobre las políticas del cobre de los años sesenta y setenta en Chile, evalúa las siguientes afirmaciones:\nI. La chilenización impulsada por Frei Montalva estableció asociaciones del Estado con compañías extranjeras.\nII. La nacionalización de 1971 fue aprobada por unanimidad en el Congreso.\nIII. La chilenización y la nacionalización transfirieron en la misma medida la propiedad de la gran minería al Estado.',choices:['Solo I y II.','Solo I y III.','Solo II y III.','I, II y III.'],why:'La chilenización desarrolló participación estatal mediante sociedades mixtas; la nacionalización de 1971 transfirió al Estado la gran minería del cobre y recibió aprobación unánime del Congreso. Fueron políticas distintas.'},
  '80':{choices:['Reconocieron víctimas y documentaron oficialmente violaciones de derechos humanos.','Determinaron condenas penales firmes para cada responsable identificado.','Sustituyeron las investigaciones judiciales mediante decisiones administrativas.','Otorgaron amnistía general a los responsables a cambio de sus testimonios.'],why:'Rettig investigó principalmente muertes y desapariciones; Valech, prisión política y tortura. Sus informes reconocen víctimas y aportan documentación, pero las comisiones no sustituyen a los tribunales penales.'},
  '81':{choices:['Apertura comercial y privatización de empresas públicas.','Aumento general de aranceles para profundizar la sustitución de importaciones.','Expansión de la propiedad industrial estatal mediante nuevas expropiaciones.','Profundización de la reforma agraria mediante redistribución de latifundios.']},
  '82':{choices:['Triunfo del No y apertura del itinerario hacia las elecciones de 1989.','Elección inmediata del presidente democrático en la misma votación.','Derogación íntegra de la Constitución por el solo resultado electoral.','Traspaso del mando presidencial antes de las elecciones parlamentarias.']},
  '83':{t:'chilexx',text:'En el proceso de democratización posterior a 1990, la reforma constitucional de 2005 dispuso la eliminación de un mecanismo de representación sin elección popular. ¿Cuál?',choices:['Senadores designados y vitalicios.','Reemplazos parlamentarios en caso de vacancia.','Atribuciones de revisión del Tribunal Constitucional.','Designación presidencial de ministros de Estado.'],why:'La reforma constitucional de 2005 eliminó los senadores designados y vitalicios, con efecto desde marzo de 2006. Se distingue la aprobación de la reforma de su entrada en vigor.'},
  '84':{choices:['Extensión del voto femenino a elecciones presidenciales y parlamentarias.','Primer reconocimiento del voto femenino limitado a elecciones municipales.','Eliminación simultánea de todos los requisitos para el sufragio adulto.','Sustitución del sufragio municipal femenino por participación solo nacional.']},
  '85':{choices:['Presidencialismo fuerte, centralismo y sufragio censitario.','Federalismo provincial, autonomía regional y sufragio censitario.','Régimen parlamentario, voto universal y Estado confesional.','Presidencialismo fuerte, sufragio universal y separación Iglesia-Estado.']},
  '86':{choices:['Movilización de producción, propaganda y población para sostener el conflicto.','Concentración del esfuerzo bélico en ejércitos sin alterar la economía civil.','Separación de la industria privada respecto del abastecimiento militar.','Mantenimiento del consumo y del trabajo al margen de la planificación bélica.']}
});
